<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { Bell, Check, LoaderCircle, Trash2 } from "lucide-vue-next";
import AppShell from "@/components/app/AppShell.vue";
import { studentWorkspaceRepository } from "@/data/repositories/studentWorkspaceRepository";
import type { UiStudentNotification } from "@/data/models/studentWorkspace";
import { setPageMeta } from "@/lib/useRouteHead";

setPageMeta({ title: "Notifications — AiStar Prep" });
const items = ref<UiStudentNotification[]>([]); const loading = ref(true); const saving = ref(false); const error = ref(""); const tab = ref<"all" | "unread" | "study" | "exams" | "account">("all");
const unread = computed(() => items.value.filter((item) => !item.read).length);
const filtered = computed(() => items.value.filter((item) => tab.value === "all" ? true : tab.value === "unread" ? !item.read : item.category === tab.value));
function setTab(value: string) { tab.value = value as typeof tab.value; }
async function load() { loading.value = true; try { items.value = await studentWorkspaceRepository.notifications(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load notifications."; } finally { loading.value = false; } }
async function persist(next: UiStudentNotification[]) { saving.value = true; try { items.value = await studentWorkspaceRepository.saveNotifications(next); } finally { saving.value = false; } }
function markAll() { void persist(items.value.map((item) => ({ ...item, read: true }))); }
function markRead(item: UiStudentNotification) { if (!item.read) void persist(items.value.map((value) => value.id === item.id ? { ...value, read: true } : value)); }
function remove(item: UiStudentNotification) { void persist(items.value.filter((value) => value.id !== item.id)); }
onMounted(load);
</script>

<template>
  <AppShell title="Notifications" :back="{ to: '/dashboard', label: 'Back to Dashboard' }">
    <div class="mx-auto max-w-4xl space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="label-mono">Account activity</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.03em]">Notifications</h2><p class="mt-1 text-[13px] text-ink3">Updates generated by your saved calendar, goals and learning activity.</p></div><button v-if="unread" class="ops-button-secondary inline-flex items-center gap-2" :disabled="saving" @click="markAll"><LoaderCircle v-if="saving" :size="13" class="animate-spin" /><Check v-else :size="13" />Mark all read</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p>
      <div class="flex gap-1 overflow-x-auto rounded-xl border border-border bg-bg-card p-1.5"><button v-for="value in ['all', 'unread', 'study', 'exams', 'account']" :key="value" class="rounded-lg px-3 py-2 text-[12px] font-semibold capitalize transition" :class="tab === value ? 'bg-blue text-white' : 'text-ink3 hover:bg-bg-soft'" @click="setTab(value)">{{ value }}</button></div>
      <div v-if="loading" class="space-y-3"><div v-for="item in 4" :key="item" class="h-24 animate-pulse rounded-2xl bg-bg-soft" /></div>
      <div v-else-if="filtered.length" class="space-y-3"><article v-for="item in filtered" :key="item.id" class="rounded-2xl border bg-bg-card p-5 transition" :class="item.read ? 'border-border' : 'border-blue-mid shadow-sm'" @click="markRead(item)"><div class="flex items-start gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-blue-light text-blue"><Bell :size="17" /></span><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-3"><div><p class="text-[14px] font-semibold">{{ item.title }}</p><p class="mt-1 text-[13px] leading-5 text-ink3">{{ item.body }}</p></div><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Delete notification" @click.stop="remove(item)"><Trash2 :size="14" /></button></div><div class="mt-3 flex items-center justify-between"><time class="text-[10px] text-ink4">{{ item.createdAt ? new Date(item.createdAt).toLocaleString() : '' }}</time><RouterLink v-if="item.to" :to="item.to" class="text-[11px] font-semibold text-blue">Open</RouterLink></div></div></div></article></div>
      <div v-else class="rounded-2xl border border-border bg-bg-card p-10 text-center"><Bell :size="28" class="mx-auto text-ink4" /><p class="mt-3 text-[15px] font-semibold">No notifications</p><p class="mt-1 text-[13px] text-ink3">New account activity will appear here.</p></div>
    </div>
  </AppShell>
</template>
